        internal static bool TryGetCoordinateSridByCacheIndex(int cacheIndex, out int srid)
        {
            if ((uint)cacheIndex < (uint)CoordinateSridByCacheIndex.Length)
            {
                srid = CoordinateSridByCacheIndex[cacheIndex];
                return true;
            }

            srid = -1;
            return false;
